    if(L2.passes > 0){ L2.passes--; D.open = true; MAP[i] = 0; L2.passHandT = 1.2; PDCELL = -1; toast("Your Fast Pass opened the door to " + ROOMS[L2G.rooms[D.r].type].name + "!"); }
