    const i = idx(mx,my);
    if(DOORS[i]) return IMG.door;
    if(LOCKERS[i]) return IMG.locker;
    const r = (pmx>=0&&pmy>=0&&pmx<N&&pmy<N) ? ROOMID[idx(pmx,pmy)] : -1;
    return r >= 0 ? IMG[ROOMS[L2G.rooms[r].type].k] : IMG.rock;
