    let wx = side===0 ? py + perp*rdy : px + perp*rdx; wx -= Math.floor(wx);
    const img = wallImg(mx,my,pmx,pmy), TS = img.width;
    let tx = Math.floor(wx*TS);
    if((side===0 && rdx>0) || (side===1 && rdy<0)) tx = TS-1 - tx;
    const lit = lightAt(pmx,pmy) === 1;
    ctx.drawImage(img, tx, 0, 1, TS, i*CW, y0, CW, lh);
    let b = lit ? 1/(1+perp*perp*0.012) : DARKB/(1+perp*perp*0.05) + Math.max(0,0.18-0.04*perp);
    if(side) b *= 0.8;
    ctx.fillStyle = "rgba(3,3,12," + (1-Math.min(1,b)).toFixed(3) + ")";
