  for(const p of PICKS){ if(p.got || !SEEN[idx(Math.floor(p.x),Math.floor(p.y))]) continue; ctx.fillStyle = "#ff8a1f"; ctx.beginPath(); ctx.arc(ox+p.x*cs, oy+p.y*cs, 3.2, 0, 7); ctx.fill(); }
  const mx = ox+P.x*cs, my = oy+P.y*cs;
