  ctx.strokeStyle = "#3ad06a"; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(mx,my); ctx.lineTo(mx+Math.cos(P.a)*9, my+Math.sin(P.a)*9); ctx.stroke();
