/* ---------- moving ---------- */
const keys = {}, joy = {on:false,id:null,cx:0,cy:0,x:0,y:0}, look = {id:null,lx:0};
function solid(x,y){ const cx = Math.floor(x), cy = Math.floor(y); return cx<0||cy<0||cx>=N||cy>=N||MAP[idx(cx,cy)]===1; }
function canMove(x,y,r){ return !(solid(x-r,y-r)||solid(x+r,y-r)||solid(x-r,y+r)||solid(x+r,y+r)); }
function update(dt){
  if(LV === 2 && L2.hiding){ updateL2(dt); return; }
  let turn = 0; if(keys.ArrowLeft||keys.KeyQ) turn -= 1; if(keys.ArrowRight||keys.KeyE) turn += 1;
  P.a += turn*2.2*dt;
  const fx = Math.cos(P.a), fy = Math.sin(P.a), sx = -fy, sy = fx;
  let mx = 0, my = 0;
  if(keys.KeyW||keys.ArrowUp){ mx += fx; my += fy; }
  if(keys.KeyS||keys.ArrowDown){ mx -= fx; my -= fy; }
  if(keys.KeyD){ mx += sx; my += sy; }
  if(keys.KeyA){ mx -= sx; my -= sy; }
  if(joy.on){ // joystick: up = forward, sideways = step sideways
    const jx = joy.x, jy = joy.y;
    mx += fx*(-jy) + sx*jx; my += fy*(-jy) + sy*jx;
  }
  const ml = Math.hypot(mx,my);
  if(ml > 0.08){
    const sp = SPEED*dt*Math.min(1,ml)/ml; mx *= sp; my *= sp;
    if(canMove(P.x+mx,P.y,0.22)) P.x += mx;
    if(canMove(P.x,P.y+my,0.22)) P.y += my;
  }
  if(LV === 2) return updateL2(dt);
  const cell = idx(Math.floor(P.x),Math.floor(P.y)), lit = LIT[cell] === 1;
  if(lit) R.streak = Math.max(0, R.streak - dt/DECAY);
  if(cell !== R.cell){
    R.cell = cell;
    if(!lit){
      R.streak += 1;
      const p = Math.min(PMAX, P0 + PINC*(Math.ceil(R.streak)-1));
      if(Math.random() < p) return scare();
    }
  }
  for(const p of PICKS){ if(!p.got && Math.hypot(p.x-P.x,p.y-P.y) < 0.55){ p.got = true; R.got++; return foundCard(p); } }
  if(!PACK.got && Math.hypot(PACK.x-P.x,PACK.y-P.y) < 0.55){ PACK.got = true; return foundPack(); }
}

/* ---------- events ---------- */
function stopMoving(){ for(const k in keys) keys[k] = false; joy.on = false; joy.x = joy.y = 0; setKnob(0,0); }
function showPanel(cardHtml, head, line, hint){
  g("bm2pc").innerHTML = cardHtml; g("bm2ph").textContent = head; g("bm2pn").textContent = line; g("bm2pk").textContent = hint;
  g("bm2panel").classList.add("on"); R.panelReady = performance.now() + PANEL_MS;
}
function foundCard(p){
  R.phase = "read"; stopMoving();
  showPanel(frameHtml(p.c), "You found one of Max's cards!", p.c[1] + "  (" + R.got + " of " + (LV===2 ? L2CARDS : 10) + ")", isTouch ? "Tap to keep going." : "Press SPACE or click to keep going.");
}
function foundPack(){
  R.phase = "pack"; stopMoving();
  if(document.exitPointerLock) try{ document.exitPointerLock(); }catch(e){}
  const pool = CARDS.filter(c=>UNLOCK_ONLY[c[0]]);
  const c = pool[Math.floor(Math.random()*pool.length)];
  R.packCard = c;
  const had = S.cards[c[0]]||0; S.cards[c[0]] = had+1; changed();
  revealCard(c, had, ()=>{ R.phase = "play"; });
}
// the same tear-open look as the Card Packs tab, shown on top of the maze
function revealCard(c, had, after){
  const box = $("#modalBox"), md = $("#modal");
  let sp=''; const n=c[2]==="common"?10:(c[2]==="rare"?20:34);
  for(let k=0;k<n;k++){const an=Math.random()*6.283,d=110+Math.random()*90;sp+='<i class="sp" style="--x:'+Math.round(Math.cos(an)*d)+'px;--y:'+Math.round(Math.sin(an)*d)+'px"></i>'}
  const glow = c[2]==="ultra"?"legendary":c[2];
  box.innerHTML = '<div class="mute" style="font-weight:700;margin-bottom:6px">You found the hidden pack! It holds a special card that the Card Packs tab never gives.</div>'+
    '<div class="stage '+glow+'"><div class="flash"></div><div class="fx">'+sp+'</div><div class="cardwrap">'+frameHtml(c)+'</div>'+
    '<div class="pk2"><img class="pbody" alt="" src="'+PACKIMG[WIN_PACK]+'"><img class="ptop" alt="" src="'+PACKIMG[WIN_PACK]+'"></div></div>'+
    '<div class="reveal-info"><div class="rar '+c[2]+'">'+rname(c[2])+'</div>'+
    '<div class="badge '+(had?"dup":"new")+'">'+(had?"Duplicate. You now have "+(had+1):"New card!")+'</div><div><button class="btn" id="mClose" disabled>OK</button></div></div>';
  md.style.zIndex = 60; md.onclick = null; md.classList.remove("hide");
  $("#mClose").onclick = ()=>{ md.classList.add("hide"); md.style.zIndex = ""; after&&after(); };
  setTimeout(()=>{const m=$("#mClose"); if(m) m.disabled=false},2800);
}
function scare(mon){
  R.phase = "scare"; R.scares++; stopMoving(); musicStop();
  const el = g("bm2scare"), msg = g("bm2smsg");
  if(LV === 2 && mon){
    g("bm2man").src = ART[mon.d.j];
    el.style.background = mon.d.k === "mEye" ? "radial-gradient(circle at 50% 55%, rgba(150,70,255,.85), #12051f 62%, #000 100%)" : "#000";
    msg.innerHTML = mon.d.name.toUpperCase() + " CAUGHT YOU<small>You start Level 2 over from the beginning. Tap or press SPACE.</small>";
    L2.hiding = null; if(L2.evt){ L2.evt.mon.gone = false; } L2.evt = null; showHideBtn();
  } else {
    g("bm2man").src = ART.oldman; el.style.background = "";
    msg.innerHTML = "THE OLD MAN CAUGHT YOU<small>You start over from the beginning. Tap or press SPACE.</small>";
  }
  msg.style.display = "none"; el.classList.remove("hit","flash"); el.classList.add("on");
  void el.offsetWidth; el.classList.add("hit","flash");
  setTimeout(()=>el.classList.remove("flash"), 90);
  setTimeout(()=>{ if(R.phase==="scare") msg.style.display = "block"; }, 1100);
  R.scareReady = performance.now() + 1100;
}
function resume(){
  if(R.phase === "read" && performance.now() >= R.panelReady){
    g("bm2panel").classList.remove("on"); R.phase = "play";
    if(LV === 2){ if(R.got >= L2CARDS) winL2(); else showHideBtn(); }
    else if(R.got >= 10) win();
  } else if(R.phase === "scare" && performance.now() >= R.scareReady){
    g("bm2scare").classList.remove("on","hit"); if(LV === 2) resetRunL2(); else resetRun(); R.phase = "play"; musicStart(); showHideBtn();
  }
}
function winL2(){
  R.phase = "won"; stopMoving(); showHideBtn();
  if(document.exitPointerLock) try{ document.exitPointerLock(); }catch(e){}
  g("bm2w2stat").textContent = "You found all " + L2CARDS + " of Max's cards behind the scenes. " + (R.scares===0 ? "Nobody caught you!" : "The monsters caught you " + R.scares + (R.scares===1?" time.":" times."));
  g("bm2win2").classList.add("on");
}
g("bm2back2").onclick = ()=>{ closeMaze(); renderBM2(); };
function win(){
  try{ localStorage.setItem("bm2_l2", "1"); }catch(e){}
  R.phase = "won"; stopMoving();
  if(document.exitPointerLock) try{ document.exitPointerLock(); }catch(e){}
  g("bm2wstat").textContent = (R.scares===0 ? "The Old Man never caught you." : "The Old Man caught you " + R.scares + (R.scares===1?" time.":" times.")) +
    (PACK.got ? " You also found the hidden pack." : " The hidden pack is still out there next time.");
  g("bm2win").classList.add("on");
}
g("bm2open").onclick = ()=>{
  closeMaze();
  let left = WIN_PACKS;
  const next = ()=>{ if(left-- > 0) openPack(WIN_PACK, true, next); else renderBM2(true); };
  next();
};

/* ---------- music: 8-bit haunted arcade tune, made by the browser ---------- */
const MUS = { ac:null, out:null, timer:null, next:0, step:0, on:false };
let muted = false; try{ muted = localStorage.getItem("bm2_mute") === "1"; }catch(e){}
const mtof = m=>440*Math.pow(2,(m-69)/12);
function mnote(t,m,dur,o){
  const c=MUS.ac, g=c.createGain(), f=c.createBiquadFilter();
  f.type="lowpass"; f.frequency.value=o.cut||5000;
  g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(o.vol,t+(o.att||0.003)); g.gain.exponentialRampToValueAtTime(0.0001,t+dur+(o.rel||0.03));
  f.connect(g); g.connect(MUS.out);
  const s=c.createOscillator(); s.type=o.wave; s.frequency.value=mtof(m);
  if(o.vib){ const l=c.createOscillator(), lg=c.createGain(); l.frequency.value=o.vib; lg.gain.value=10; l.connect(lg); lg.connect(s.detune); l.start(t); l.stop(t+dur+0.2); }
  s.connect(f); s.start(t); s.stop(t+dur+(o.rel||0.03)+0.05);
}
const CHORDS=[[57,60,64],[53,57,60],[50,53,57],[52,56,59]];
const MEL=[69,null,null,72,null,71,null,69, 68,null,null,null,64,null,null,null, 65,null,null,69,null,68,null,65, 64,null,null,null,null,null,null,null];
function mtick(){
  const b=60/132/2;
  while(MUS.next < MUS.ac.currentTime+0.25){
    const t=MUS.next, i=MUS.step, c=CHORDS[Math.floor(i/16)%4];
    mnote(t,c[i%3]+12,b*0.45,{wave:"square",vol:0.08,rel:0.02});
    if(i%4===0) mnote(t,c[0]-12,b*1.8,{wave:"triangle",vol:0.16,att:0.005});
    const m=MEL[Math.floor(i/2)%32]; if(m && i%2===0) mnote(t,m+12,b*1.6,{wave:"square",vol:0.075,cut:3500,vib:6,rel:0.04});
    MUS.step++; MUS.next+=b;
  }
}
function musicStart(){
  if(muted || MUS.on) return;
  try{
    if(!MUS.ac) MUS.ac = new (window.AudioContext||window.webkitAudioContext)();
    if(MUS.ac.state==="suspended") MUS.ac.resume();
    const c=MUS.ac; MUS.out=c.createGain(); MUS.out.gain.value=0.0001; MUS.out.gain.exponentialRampToValueAtTime(0.8,c.currentTime+0.5); MUS.out.connect(c.destination);
    MUS.on=true; MUS.step=0; MUS.next=c.currentTime+0.1; mtick(); MUS.timer=setInterval(mtick,60);
  }catch(e){ MUS.on=false; }
}
function musicStop(){
  clearInterval(MUS.timer); MUS.timer=null;
  if(MUS.on && MUS.out){ const o=MUS.out, c=MUS.ac; try{ o.gain.cancelScheduledValues(c.currentTime); o.gain.setValueAtTime(Math.max(0.0001,o.gain.value),c.currentTime); o.gain.exponentialRampToValueAtTime(0.0001,c.currentTime+0.3); }catch(e){} setTimeout(()=>{ try{o.disconnect()}catch(e){} },500); }
  MUS.on=false; MUS.out=null;
}
function sndLabel(){ g("bm2snd").textContent = muted ? "Sound: Off" : "Sound: On"; }
g("bm2snd").onclick = e=>{
  e.stopPropagation(); muted = !muted;
  try{ localStorage.setItem("bm2_mute", muted ? "1" : "0"); }catch(err){}
  sndLabel(); if(muted) musicStop(); else if(R.phase!=="scare") musicStart();
};
sndLabel();

/* ---------- open / close ---------- */
let isTouch = false;
function openMaze(level){
  if(!READY) return;
  LV = level === 2 ? 2 : 1;
  newRun();
  open = true; ov.classList.add("on"); fit(); document.body.style.overflow = "hidden";
  ["bm2panel","bm2win","bm2win2","bm2scare"].forEach(id=>g(id).classList.remove("on","hit"));
  g("bm2leave").classList.remove("arm"); g("bm2leave").textContent = "Leave"; R.leaveArm = false;
  stopMoving(); R.phase = "play"; sndLabel(); musicStart(); showHideBtn();
  last = performance.now(); cancelAnimationFrame(rafId); rafId = requestAnimationFrame(frame);
}
function closeMaze(){
  open = false; R.phase = "off"; ov.classList.remove("on"); document.body.style.overflow = "";
  cancelAnimationFrame(rafId); stopMoving(); musicStop(); g("bm2hide").style.display = "none";
  if(document.exitPointerLock) try{ document.exitPointerLock(); }catch(e){}
}
g("bm2leave").onclick = e=>{
  e.stopPropagation();
  if(!R.leaveArm){ R.leaveArm = true; g("bm2leave").classList.add("arm"); g("bm2leave").textContent = "Tap again to leave"; setTimeout(()=>{ R.leaveArm=false; const b=g("bm2leave"); b.classList.remove("arm"); b.textContent="Leave"; }, 3000); return; }
  closeMaze(); renderBM2();
};

/* ---------- input ---------- */
function lock(){ try{ const r = cv.requestPointerLock && cv.requestPointerLock(); if(r && r.catch) r.catch(()=>{}); }catch(e){} }
document.addEventListener("pointerlockchange", ()=>{ locked = document.pointerLockElement === cv; });
cv.addEventListener("mousedown", ()=>{ if(isTouch) return; if(R.phase==="play" && !locked) lock(); else resume(); });
stage.addEventListener("mousedown", e=>{ if(isTouch) return; if(e.target.closest && (e.target.closest("#bm2panel")||e.target.closest("#bm2scare"))) resume(); });
g("bm2hide").onclick = e=>{ e.stopPropagation(); hideToggle(); };
addEventListener("mousemove", e=>{ if(open && locked && R.phase==="play" && !(LV===2 && L2.hiding)) P.a += (e.movementX||0)*0.0025; });
addEventListener("keydown", e=>{
  if(!open) return;
  if(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight","Space"].includes(e.code)) e.preventDefault();
  if(LV === 2 && R.phase === "play" && e.code === "Space"){ if(!e.repeat) hideToggle(); return; }
  if(R.phase === "play" && !(LV===2 && L2.hiding)) keys[e.code] = true;
  if(e.code === "Space" || e.code === "Enter") resume();
});
addEventListener("keyup", e=>{ keys[e.code] = false; });
addEventListener("blur", ()=>stopMoving());

// touch: joystick in the lower left, drag anywhere else to look, tap to close pop-ups
function stagePt(t){ const r = stage.getBoundingClientRect(), s = r.width / W; return {x:(t.clientX - r.left)/s, y:(t.clientY - r.top)/s}; }
const JOY = {x:150, y:H-150, r:110};
function setKnob(x,y){ const k = document.querySelector("#bm2joy i"); if(k) k.style.transform = "translate("+(x*JOY.r*0.75)+"px,"+(y*JOY.r*0.75)+"px)"; }
ov.addEventListener("touchstart", e=>{
  if(!isTouch){ isTouch = true; ov.classList.add("touch"); }
  if(e.target.closest && e.target.closest("button")) return;
  e.preventDefault();
  if(R.phase !== "play"){ resume(); return; }
  for(const t of e.changedTouches){
    const p = stagePt(t);
    if(joy.id === null && p.x < W*0.42 && p.y > H*0.38){ joy.id = t.identifier; joy.on = true; moveJoy(p); }
    else if(look.id === null){ look.id = t.identifier; look.lx = p.x; }
  }
}, {passive:false});
function moveJoy(p){ let x = (p.x - JOY.x)/JOY.r, y = (p.y - JOY.y)/JOY.r; const l = Math.hypot(x,y); if(l > 1){ x/=l; y/=l; } joy.x = x; joy.y = y; setKnob(x,y); }
ov.addEventListener("touchmove", e=>{
  e.preventDefault();
  for(const t of e.changedTouches){
    const p = stagePt(t);
    if(t.identifier === joy.id){ if(R.phase==="play") moveJoy(p); }
    else if(t.identifier === look.id){ if(R.phase==="play" && !(LV===2 && L2.hiding)) P.a += (p.x - look.lx)*0.006; look.lx = p.x; }
  }
}, {passive:false});
function endTouch(e){
  for(const t of e.changedTouches){
    if(t.identifier === joy.id){ joy.id = null; joy.on = false; joy.x = joy.y = 0; setKnob(0,0); }
    if(t.identifier === look.id) look.id = null;
  }
}
ov.addEventListener("touchend", endTouch); ov.addEventListener("touchcancel", endTouch);

/* ---------- loop ---------- */
let last = 0;
function frame(now){
  if(!open) return;
  const dt = Math.min(0.05, (now-last)/1000); last = now;
  if(R.phase === "play") update(dt);
  drawFloor(); drawWalls(); drawSprites(now/1000); vignette(); if(LV === 2) drawL2Overlay(now/1000); drawHUD();
  rafId = requestAnimationFrame(frame);
}

/* ---------- the tab ---------- */
